import type {
  FullResult,
  Reporter,
  TestCase,
  TestResult,
} from "@playwright/test/reporter";

/** Compact progress plus immediate failure evidence for long serial browser runs. */
export default class BrowserReporter implements Reporter {
  private counts: Record<string, number> = {};

  onStdOut(chunk: string | Buffer) {
    if (chunk.toString().includes("Auditing ")) process.stdout.write(chunk);
  }

  onTestEnd(test: TestCase, result: TestResult) {
    this.counts[result.status] = (this.counts[result.status] ?? 0) + 1;
    console.log(`${result.status}: ${test.titlePath().join(" / ")}`);
    if (result.status !== test.expectedStatus)
      for (const error of result.errors)
        console.log(error.message ?? error.value);
  }

  onEnd(result: FullResult) {
    console.log(`Browser run ${result.status}: ${JSON.stringify(this.counts)}`);
  }
}
